-- The search results page (/search/?q=), as a template sites can edit under Templates. Generated
-- from src/lib/content/search-template.ts. Sites that already have a `search` template keep theirs.
insert into public.templates (kind, slug, title, content)
select 'template', 'search', 'Search results', $json${"root":{"props":{}},"content":[{"type":"part","props":{"id":"t-search-header","attrs":{"slug":"header"}}},{"type":"section","props":{"id":"t-search-main","attrs":{"tag":"main","style":{"padding":{"top":"var(--space-70)","right":"var(--space-50)","bottom":"var(--space-80)","left":"var(--space-50)"}},"layout":{"type":"constrained","contentSize":"720px"},"gap":"var(--space-50)"},"children":[{"type":"archive-title","props":{"id":"t-search-title","attrs":{"level":1}}},{"type":"search-form","props":{"id":"t-search-form","attrs":{}}},{"type":"collection","props":{"id":"t-search-results","attrs":{"query":{"inherit":true,"perPage":10},"display":"list","pagination":"numbers","card":"custom","emptyText":"Nothing matched your search. Try other words."},"children":[{"type":"collection-items","props":{"id":"t-search-items","attrs":{"layout":{"type":"flow"}},"children":[{"type":"section","props":{"id":"t-search-item","attrs":{"style":{"padding":{"bottom":"var(--space-50)"},"margin":{"bottom":"var(--space-50)"},"borderBottom":{"width":"1px","color":"var(--color-surface-alt)"}},"layout":{"type":"flow"},"gap":"var(--space-20)"},"children":[{"type":"entry-title","props":{"id":"t-search-item-title","attrs":{"level":2,"link":true,"style":{"fontFamily":"var(--font-display)","fontSize":"var(--text-x-large)"}}}},{"type":"entry-excerpt","props":{"id":"t-search-item-excerpt","attrs":{"length":30}}}]}}]}}]}}]}},{"type":"part","props":{"id":"t-search-footer","attrs":{"slug":"footer"}}}],"zones":{}}$json$::json
where not exists (select 1 from public.templates where kind = 'template' and slug = 'search');
